python - <<'PY'
import csv,numpy as np
from pymatgen.core import Structure
for r in csv.DictReader(open('nlo_pool.csv')):
 if r['candidate_id'] not in {'c030','c037','c041','c050','c057','c078','c081','c038','c055'}:continue
 s=Structure.from_str(r['poscar'],fmt='poscar'); anions=set(s.composition.as_dict())&{'S','Se','As','P'}
 if r['candidate_id']=='c038':anions={'S'}
 cats=set(s.composition.as_dict())-anions;ts={}
 for el in sorted(cats):
  t=np.zeros((3,3,3))
  for a in s:
   if str(a.specie)!=el:continue
   nn=sorted([n for n in s.get_neighbors(a,4.5) if str(n.specie) in anions],key=lambda n:n.nn_distance)[:3 if el=='Sb' else 4]
   vs=np.array([(n.coords-a.coords)/n.nn_distance for n in nn]); t+=np.einsum('ni,nj,nk->ijk',vs,vs,vs)
  ts[el]=t
 print(r['candidate_id'],{el:round(float(np.max(abs(t))/s.volume*1000),2) for el,t in ts.items()})
 for a in ts:
  for b in ts:
   if a<b:print('orient',a,b,round(float(np.sum(ts[a]*ts[b])/(np.linalg.norm(ts[a])*np.linalg.norm(ts[b]))),3))
